use serde_json::{Value, Map};
use std::collections::BTreeMap;

pub fn solve(input: Value) -> Value {
    if let Value::Array(rows) = input {
        let mut map = BTreeMap::new();
        for row in rows {
            if let Value::Array(vec) = row {
                if vec.len() == 2 {
                    if let (Value::Number(key), Value::Number(value)) = (&vec[0], &vec[1]) {
                        map.insert(key.as_i64().unwrap(), value.as_i64().unwrap());
                    }
                }
            }
        }
        let mut result = Vec::new();
        for (key, value) in map {
            result.push(Value::Array(vec![Value::Number(key), Value::Number(value)]));
        }
        Value::Array(result)
    } else {
        Value::Null
    }
}
